static async size(repository: RecordRepository, commit: string, deadline: Deadline): Promise<TipSize> {
	const listing = await repository.listing(commit, deadline, listingLimit);
	if (listing === undefined) return TipSize.unlisted();
	const { total } = await StateTree.#sizes(repository, listing.entries, deadline);
	return TipSize.of({ entries: listing.entries.length, recordBytes: total, listingBytes: listing.bytes });
}

async listing(
	treeish: string,
	deadline: Deadline,
	maxBytes: number,
): Promise<{ entries: TreeEntry[]; bytes: number } | undefined> {
	return this.#list(["ls-tree", "-r", "-z", "--full-tree", treeish], treeish, deadline, maxBytes);
}

async sizes(oids: readonly string[], deadline: Deadline): Promise<Map<string, number>> {
	const sizes = new Map<string, number>();
	if (oids.length === 0) return sizes;
	const output = await this.#succeed(["cat-file", "--batch-check=%(objectname) %(objectsize)"], deadline, {
		input: `${oids.join("\n")}\n`,
	});
	for (const line of output.split("\n")) {
		const [oid, size] = line.split(" ");
		if (oid !== undefined && size !== undefined && /^\d+$/.test(size)) sizes.set(oid, Number(size));
	}
	return sizes;
}

